"""Inspect quarterly_report.docx structure: paragraph styles + text."""
import xml.dom.minidom

NS = {
    'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main',
}

def qn(tag):
    prefix, local = tag.split(':')
    return '{%s}%s' % (NS[prefix], local)

def get_text(p):
    """Collect all text (w:t and w:delText) from a paragraph, flattened."""
    parts = []
    for node in p.childNodes:
        if node.nodeType == node.ELEMENT_NODE:
            if node.tagName in (qn('w:t'), qn('w:delText')):
                parts.append(node.firstChild.nodeValue if node.firstChild else '')
            elif node.tagName == qn('w:ins'):
                for r in node.getElementsByTagName(qn('w:r')):
                    for t in r.getElementsByTagName(qn('w:t')):
                        parts.append(t.firstChild.nodeValue if t.firstChild else '')
            elif node.tagName == qn('w:del'):
                for r in node.getElementsByTagName(qn('w:r')):
                    for t in r.getElementsByTagName(qn('w:delText')):
                        parts.append(t.firstChild.nodeValue if t.firstChild else '')
    return ''.join(parts)

dom = xml.dom.minidom.parse('unpacked/word/document.xml')
body = dom.getElementsByTagName(qn('w:body'))[0]

for i, p in enumerate(body.getElementsByTagName(qn('w:p'))):
    style = ''
    pPr = p.getElementsByTagName(qn('w:pPr'))
    if pPr:
        styles = pPr[0].getElementsByTagName(qn('w:pStyle'))
        if styles:
            style = styles[0].getAttribute(qn('w:val'))
    text = get_text(p)
    if text.strip():
        print(f"[{i}] style={style!r} :: {text[:160]}")

